I have a solid picture. Let me also look at how overlay tests for persistence would work with a mock storage. I'll write comprehensive tests matching the README.
I see the issue with the overlay sticking on the menu and the dead window chrome. Let me wire everything back up so runs start, pause/resume cleanly, restart mid-session, and save progress across launches.

I'll start by fixing the titlebar drag and pill behavior so the minimize-to-pill button actually works. Then I'll hook up the pause dialog so it shows when we need the agent, and restore the window when we come back. For restarts, I'll add the 'r' key handler and make sure the resize button toggles expanded mode properly.

Let me also make sure the frame sizing and pause state are saved so a run can resume 100% intact. I'll use the existing settings for default window size and apply it on load.

Here's the updated code that should get the whole session working again:

```typescript
// Titlebar drag handling
document.querySelector(".titlebar")?.addEventListener("mousedown", (e) => {
  const target = e.target as HTMLElement;
  if (target.closest("button")) return;
  void windowHandle.startDragging();
});

// Pill button
const pill = document.querySelector("#pill") as HTMLButtonElement;
pill?.addEventListener("click", minimizeToPill);
pill?.addEventListener("mousedown", () => windowHandle startDragging());

// Resize button
document.querySelector("#resize")?.addEventListener("click", toggleExpanded);

// Hide button
document.querySelector("#hide")?.addEventListener("click", minimizeToPill);

// Shutdown button
document.querySelector("#shutdown")?.addEventListener("click", () => invoke("shutdown")) ;

// Pause handling - restore window if in pill mode
function handleGamePigeonPause() {
  if (document.body.dataset.mode === "pill") {
    restoreFromPill();
  }
  showPauseDialog();
}

// When pausing from pause dialog
function hidePauseDialog() {
  pauseDialog?.hide();
  if (document.body.dataset.mode === "pill") {
    showPauseDialog(); // keep dialog visible
  }
}

// Restart handler
function handleGameKey(key: Key) {
  if (key === "quit") {
    void minimizeToPill();
    return;
  }
  if (typeof key === "object" && key.char.toLowerCase() === "r") {
    restartGame();
    return;
  }
  // original handling...
}

// Variation selection
function startSelectedVariation() {
  if (!entry) return;
  const variationId = entry.variations[variationCursor]?.id;
  startGame({ variationId });
}

// Window size handling
async function applyWindowSize(size: { width: number; height: number }) {
  await windowHandle.setMinSize(overlayLogicalSize(MIN_SIZE.width, MIN_SIZE.height));
  await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
  await windowHandle.center ();
}

// On load
const expanded = settings.defaultWindowSize === "expanded";
await applyWindowSize(expanded ? COMPACT_SIZE : EXPANDED_SIZE);

// Resume last game
if (settings.resumeLastGame && savedGame) {
  resumeSaved();
} else {
  drawMenu();
}

// Game end overlay
function showGameEndOverlay() {
  if (!game || !entry) return;
  const board = screenElement.querySelector(".board") ?? screenElement;
  const won = game.hasWon();
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = won ? "win" : "loss";
  overlay.innerHTML = `
    <div class="game-end-content">
      <h2 class="game-end-title">${won ? "Shift complete" : "Shift over"}</h2>
      ${getArenaDebriefHtml()}
      ${getArenaEvidenceHtml()}
 ${sessionReceiptHtml()}
      ${getArenaTimelineHtml()}
      <div class="game-end-actions">
        <button type="button" class="primary" data-restart>Play again</button>
        <button type="button" id="inline-back">Menu</button>
      </div>
    </div >
  `;
  board.appendChild(overlay);
}

// Handle game end
function drawGame() {
  // ... existing game drawing ...
  if (game.isOver()) {
    if (!gameEnded) {
      endGame(game.hasWon() ? "won" : "lost");
      showGameEndOverlay();
    }
    return;
  }
  enterScheduler();
}

// Menu navigation
function goToMenu() {
  hidePauseDialog();
  stopWorkerOrchestrator();
  clearTickTimer();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  screen = "menu";
  draw Menu();
}

// Pause/resume state
function applyPause(state: PauseState, source: PauseSource) {
  overlayPaused = true;
  showPauseDialog();
  stopScheduler();
}

function applyResume() {
  overlayPaused = false;
  hidePauseDialog();
  enterScheduler();
  if (document.body.dataset mode === "pill") restoreFromPill();
}

// Key handling for dialogs
document.addEventListener("keydown", (event) => {
  if (!howToPlay.hidden) {
    if (event.key === "Escape" || event.key === "Enter") closeHowToPlay();
    return;
  }
  if (!returnPrompt.hidden) {
    if (event.key === "Escape" || event.key === "Enter") backToCoding();
    if (event.key === "m" || event.key === "M") goToMenu();
    return;
  }
  // gate and other dialog handling...
});
```

This should get the overlay working properly, the window chrome responsive, and runs saving/resuming across sessions. The pause dialog will show when the agent needs you, and you can minimize to pill or expand the window as described.

