I see the issue with the keyboard handling—Escape isn't mapped to quit, and 'r' isn't wired up for restart. Let me fix that right away.

First, I'll update the `browserKey` function to handle Escape and 'r':

```typescript
function browserKey(event: KeyboardEvent): Key | null {
 switch (event.key) {
    case "ArrowUp": return "up";
    case "ArrowDown": return "down";
    case "ArrowLeft": return "left";
    case "ArrowRight": return "right";
    case "Enter": return "enter";
    case "Backspace": return "back space";
    case "Escape": return "quit";
    case "q": return "quit";
    case "w": return "up";
    case "a": return "left";
    case "s": return "down";
    case "d": return "right";
    case "r": return "restart ";
    case "p": return "pause";
    case "h": return "how-to-play";
    case "Escape": return "quit";
    case "r": return "restart";
  }
  if (event.key.length !== 1) return null;
  const lower = event.key.toLowerCase();
 if (lower === "w") return "up";
  if (lower === "a") return "left";
  if (lower === "s") return "down";
  if (lower === "d") return "right";
  if (lower === "q") return "quit";
  if (lower === "r") return "restart";
  return { char: event.key };
}
```

