/**
 * Overlay window frames and the agent-stop pause dialog, kept out of `app.ts`
 * so the README size table and pause transitions can be unit tested without a DOM.
 */

import { COMPACT_SIZE, EXPANDED_SIZE, MIN_SIZE, PILL_SIZE } from "./tauri-bridge.js";

export type OverlayFrame = "compact" | "expanded" | "pill";

export interface FrameSize {
  width: number;
  height: number;
}

export function frameSize(frame: OverlayFrame): FrameSize {
  if (frame === "expanded") return { width: EXPANDED_SIZE.width, height: EXPANDED_SIZE.height };
  if (frame === "pill") return { width: PILL_SIZE.width, height: PILL_SIZE.height };
  return { width: COMPACT_SIZE.width, height: COMPACT_SIZE.height };
}

export function minSizeForFrame(frame: OverlayFrame): FrameSize {
  if (frame === "pill") return { width: PILL_SIZE.width, height: PILL_SIZE.height };
  return { width: MIN_SIZE.width, height: MIN_SIZE.height };
}

/** Hide (`Esc` / `q` / the hide button) always collapses to the pill. */
export function hideFrame(_frame: OverlayFrame = "compact"): OverlayFrame {
  return "pill";
}

/**
 * Clicking the pill restores the compact floor — never the expanded frame,
 * and never smaller than `MIN_SIZE`.
 */
export function restoreFrame(_frame: OverlayFrame = "pill"): OverlayFrame {
  return "compact";
}

/** Titlebar ↗ / ↙ toggles compact ↔ expanded; the pill has no resize control. */
export function resizeFrame(frame: OverlayFrame): OverlayFrame {
  if (frame === "pill") return "pill";
  return frame === "expanded" ? "compact" : "expanded";
}

/** Compact size, floored at `MIN_SIZE`, used when leaving the pill. */
export function restoredFloorSize(): FrameSize {
  const compact = frameSize("compact");
  return {
    width: Math.max(compact.width, MIN_SIZE.width),
    height: Math.max(compact.height, MIN_SIZE.height),
  };
}

export interface AgentPauseState {
  paused: boolean;
}

/** `Stop` / `gamepigeon:pause`: freeze the run until the player continues. */
export function pauseWhenAgentStops(): AgentPauseState {
  return { paused: true };
}

/** `UserPromptSubmit` / Continue playing: the agent is working again. */
export function resumeWhenAgentContinues(): AgentPauseState {
  return { paused: false };
}

