import { describe, expect, test } from "bun:test";
import { COMPACT_SIZE, EXPANDED_SIZE, MIN_SIZE, PILL_SIZE } from "./tauri-bridge.js";
import {
  frameSize,
  hideFrame,
  minSizeForFrame,
  pauseWhenAgentStops,
  resizeFrame,
  restoreFrame,
  restoredFloorSize,
  resumeWhenAgentContinues,
} from "./pause-state.js";

describe("window frames", () => {
  test("compact, expanded, and pill match the README table", () => {
    expect(frameSize("compact")).toEqual(COMPACT_SIZE);
    expect(frameSize("expanded")).toEqual(EXPANDED_SIZE);
    expect(frameSize("pill")).toEqual(PILL_SIZE);
  });

  test("hide collapses to the pill", () => {
    expect(hideFrame("compact")).toBe("pill");
    expect(hideFrame("expanded")).toBe("pill");
    expect(frameSize(hideFrame("compact"))).toEqual(PILL_SIZE);
  });

  test("clicking the pill restores compact, never smaller than MIN_SIZE", () => {
    expect(restoreFrame("pill")).toBe("compact");
    expect(restoredFloorSize().width).toBeGreaterThanOrEqual(MIN_SIZE.width);
    expect(restoredFloorSize().height).toBeGreaterThanOrEqual(MIN_SIZE.height);
    expect(restoredFloorSize()).toEqual({
      width: Math.max(COMPACT_SIZE.width, MIN_SIZE.width),
      height: Math.max(COMPACT_SIZE.height, MIN_SIZE.height),
    });
  });

  test("the expand control toggles compact ↔ expanded and leaves the pill alone", () => {
    expect(resizeFrame("compact")).toBe("expanded");
    expect(resizeFrame("expanded")).toBe("compact");
    expect(resizeFrame("pill")).toBe("pill");
  });

  test("the restored floor still enforces MIN_SIZE, the pill does not", () => {
    expect(minSizeForFrame("compact")).toEqual(MIN_SIZE);
    expect(minSizeForFrame("expanded")).toEqual(MIN_SIZE);
    expect(minSizeForFrame("pill")).toEqual(PILL_SIZE);
  });
});

describe("agent pause", () => {
  test("Stop freezes the run; Continue / a new prompt releases it", () => {
    expect(pauseWhenAgentStops()).toEqual({ paused: true });
    expect(resumeWhenAgentContinues()).toEqual({ paused: false });
  });
});

