import { REGISTRY } from "../src/games/registry.js";
import {
  STORAGE_KEY,
  clearSavedGame,
  loadSavedGame,
  restoreGame,
  saveSavedGame,
  type SavedGame,
} from "./persistence.js";

function memoryStorage(initial: Record<string, string> = {}): Storage {
  const map = new Map(Object.entries(initial));
  return {
    get length() { return map.size; },
    clear() { map.clear(); },
    getItem(key) { return map.has(key) ? map.get(key)! : null; },
    key(index) { return [...map.keys()][index] ?? null; },
    removeItem(key) { map.delete(key); },
    setItem(key, value) { map.set(key, String(value)); },
  };
}

function sample(overrides: Partial<SavedGame> = {}): SavedGame {
  return {
    schemaVersion: 1,
    ownerId: "usr_test",
    gameId: "restaurant-arena",
    gameVersion: "1",
    variationId: "dinner-rush",
    seed: 218220,
    actions: ["sim_toggle", "tick"],
    ...overrides,
  };
}

describe("saved run record", () => {
  test("round-trips a valid SavedGame under the README storage key", () => {
    const storage = memoryStorage();
    const saved = sample();
    saveSavedGame(saved, storage);
    expect(storage.getItem(STORAGE_KEY)).toContain("restaurant-arena");
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("ending a shift leaves the record; restart throws it away", () => {
    const storage = memoryStorage();
    saveSavedGame(sample(), storage);
    expect(loadSavedGame(storage)?.seed).toBe(218220);
    // Returning to the menu does not call clearSavedGame.
    expect(loadSavedGame(storage)?.actions).toEqual(["sim_toggle", "tick"]);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("rejects a malformed or oversized record", () => {
    const storage = memoryStorage({
      [STORAGE_KEY]: JSON.stringify({ schemaVersion: 1, gameId: "restaurant-arena" }),
    });
    expect(loadSavedGame(storage)).toBeNull();
    expect(loadSavedGame(memoryStorage({ [STORAGE_KEY]: "not-json" }))).toBeNull();
  });
});

describe("restoreGame", () => {
  test("replays accepted actions onto the same seed", () => {
    const entry = REGISTRY.find((item) => item.id === "restaurant-arena")!;
    const restored = restoreGame(entry, sample());
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual(["sim_toggle", "tick"]);
    expect(restored!.game.state()).toEqual(entry.create!("dinner-rush").reset(218220) as never);
    const expected = entry.create!("dinner-rush");
    expected.reset(218220);
    expected.step("sim_toggle");
    expected.step("tick");
    expect(restored!.game.state()).toEqual(expected.state());
  });

  test("refuses a different game version instead of inventing a run", () => {
    const entry = REGISTRY.find((item) => item.id === "restaurant-arena")!;
    expect(restoreGame(entry, sample({ gameVersion: "0" }))).toBeNull();
    expect(restoreGame(entry, sample({ gameId: "missing" }))).toBeNull();
  });
});
