function dialogElement(id: string): HTMLElement | null {
  return document.querySelector<HTMLElement>(`#${id}`);
}

function dialogOpen(id: string): boolean {
  const element = dialogElement(id);
  return Boolean(element && !element.hidden);
}

function setDialogHidden(id: string, hidden: boolean): void {
  const element = dialogElement(id);
  if (element) element.hidden = hidden;
}

function currentVariation(): string {
  return currentVariationId
    || entry?.variations[variationCursor]?.id
    || entry?.variations[0]?.id
    || "classic";
}

function randomSeed(avoid?: number): number {
  let seed: number;
  do {
    seed = Math.floor(Math.random() * 0x7fffffff);
  } while (avoid !== undefined && seed === avoid);
  return seed;
}

function persistActiveGame(): void {
  if (!game || !entry || gameEnded) return;
  const record: SavedGame = {
    schemaVersion: 1,
    ownerId: signedInUser()?.id ?? "",
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: currentVariation(),
    seed: currentSeed,
    actions: currentActions,
  };
  saveSavedGame(record);
  savedGame = record;
}

function recordAcceptedAction(action: string, actor: TraceActor): void {
  currentActions.push(action);
  actionsTaken++;
  if (activeTrace) {
    appendOverlayAction(activeTrace, action, actor);
    persistTrace(activeTrace);
    scheduleTraceFlush(activeTrace);
  }
  persistActiveGame();
}

function clearTickTimer(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

function scheduleTick(): void {
  clearTickTimer();
  if (!game || game.isOver() || overlayPaused || replaying) return;
  const ms = game.tickMs?.() ?? 0;
  if (ms <= 0) return;
  tickTimer = window.setTimeout(() => {
    tickTimer = undefined;
    if (game && !game.isOver() && !overlayPaused) performAction("tick");
  }, ms);
}

function enterScheduler(): void {
  clearTickTimer();
  if (!game || game.isOver() || overlayPaused || replaying) {
    workerOrchestrator?.pause();
    return;
  }
  if (workerOrchestrator) {
    if ((game.tickMs?.() ?? 0) > 0) workerOrchestrator.start();
    else workerOrchestrator.pause();
    return;
  }
  scheduleTick();
}

function currentFrame(): OverlayFrame {
  return overlayFrame;
}

async function applyWindowChrome(): Promise<void> {
  const frame = currentFrame();
  const size = frame === "pill" ? frameSize("pill") : frame === "expanded" ? frameSize("expanded") : restoredFloorSize();
  const min = minSizeForFrame(frame);
  if (frame === "pill") document.body.dataset.mode = "pill";
  else delete document.body.dataset.mode;
  const resize = document.querySelector<HTMLButtonElement>("#resize");
  if (resize) {
    const expanded = frame === "expanded";
    resize.textContent = expanded ? "↙" : "↗";
    resize.setAttribute("aria-label", expanded ? "Compact overlay" : "Expand overlay");
    resize.title = expanded ? "Compact" : "Expand or compact";
  }
  try {
    await windowHandle.setMinSize(overlayLogicalSize(min.width, min.height));
    await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
    if (frame !== "pill") await windowHandle.center();
  } catch {
    // Preview and older shells still paint; size is best-effort.
  }
}

function minimizeToPill(): void {
  overlayFrame = hideFrame(overlayFrame);
  hidePauseDialog();
  setDialogHidden("how-to-play", true);
  setDialogHidden("signout-prompt", true);
  void applyWindowChrome();
}

function restoreFromPill(): void {
  if (overlayFrame !== "pill") return;
  overlayFrame = restoreFrame(overlayFrame);
  void applyWindowChrome();
}

function toggleExpanded(): void {
  overlayFrame = resizeFrame(overlayFrame);
  void applyWindowChrome();
}

function hidePauseDialog(): void {
  setDialogHidden("return-prompt", true);
}

function showPauseDialog(): void {
  if (overlayFrame === "pill") restoreFromPill();
  setDialogHidden("how-to-play", true);
  setDialogHidden("signout-prompt", true);
  setDialogHidden("return-prompt", false);
}

function pauseForAgent(): void {
  overlayPaused = pauseWhenAgentStops().paused;
  workerOrchestrator?.pause();
  clearTickTimer();
  showPauseDialog();
}

function continuePlaying(): void {
  overlayPaused = resumeWhenAgentContinues().paused;
  hidePauseDialog();
  enterScheduler();
}

function backToCoding(): void {
  hidePauseDialog();
  minimizeToPill();
}

function openHowToPlay(): void {
  howToPlayFromPause = dialogOpen("return-prompt");
  hidePauseDialog();
  setDialogHidden("how-to-play", false);
}

function closeHowToPlay(): void {
  setDialogHidden("how-to-play", true);
  if (howToPlayFromPause && overlayPaused) showPauseDialog();
  howToPlayFromPause = false;
}

function openSignOutPrompt(): void {
  setDialogHidden("signout-prompt", false);
}

function closeSignOutPrompt(): void {
  setDialogHidden("signout-prompt", true);
}

async function confirmSignOut(): Promise<void> {
  closeSignOutPrompt();
  try {
    await signOut();
  } catch {
    return;
  }
  stopWorkerOrchestrator();
  clearTickTimer();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  entry = undefined;
  overlayPaused = false;
  hidePauseDialog();
  setDialogHidden("how-to-play", true);
  renderAccountChip();
  drawGate();
}

function goToMenu(): void {
  overlayPaused = false;
  hidePauseDialog();
  setDialogHidden("how-to-play", true);
  setDialogHidden("signout-prompt", true);
  stopWorkerOrchestrator();
  clearTickTimer();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  if (game && !gameEnded) persistActiveGame();
  game = undefined;
  screen = "menu";
  cursor = -1;
  drawMenu();
}

function endGame(reason: EpisodeEndReason): void {
  if (gameEnded || !game || !entry) return;
  gameEnded = true;
  stopWorkerOrchestrator();
  clearTickTimer();
  cancelTraceFlush();
  const endedAt = Date.now();
  const score = game.score();
  const success = game.hasWon();
  const completed = reason === "game_over" || reason === "won" || reason === "lost";
  const variationId = currentVariation();
  if (activeTrace) {
    lastReplay = {
      entry,
      variationId,
      seed: activeTrace.seed,
      actions: activeTrace.actions.map((item) => item.action),
    };
    submitTrace(activeTrace, reason, completed ? score : undefined);
    activeTrace = undefined;
  }
  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: variationId,
    outcome: completed ? "completed" : "abandoned",
    score,
    success,
    duration_ms: Math.max(0, endedAt - gameStartedAt),
    actions_taken: actionsTaken,
  }, sessionReceiptId);
  if (completed) {
    clearSavedGame();
    savedGame = undefined;
    void invoke("append_local_score", {
      score: {
        game_id: sessionReceiptId ?? `game_${endedAt}`,
        game_type: entry.id,
        variation_id: variationId,
        score,
        success,
        completed_at: new Date(endedAt).toISOString(),
        duration_ms: Math.max(0, endedAt - gameStartedAt),
        platform: "overlay",
      },
    }).then(() => refreshLocalScores()).catch(() => undefined);
  }
}

function showGameEndOverlay(): void {
  if (!game || !entry) return;
  const board = screenElement.querySelector(".board") ?? screenElement;
  if (board.querySelector(".game-end-overlay")) return;
  const won = game.hasWon();
  const isArena = game.name === "restaurant-arena";
  const overlay = document.createElement("div");
  overlay.className = "game-end-overlay";
  overlay.dataset.tone = won ? "win" : "loss";
  overlay.innerHTML = `
    <div class="game-end-content${isArena ? " arena-end-content" : ""}">
      <h2 class="game-end-title">${won ? "Shift complete" : "Shift over"}</h2>
      ${getArenaDebriefHtml()}
      ${getArenaEvidenceHtml()}
      ${sessionReceiptHtml()}
      ${getArenaTimelineHtml()}
      <div class="game-end-actions">
        <button type="button" class="primary" data-restart>Play again</button>
        ${isArena ? `<div class="export-trace-group">
          <button type="button" class="export-trace-btn" data-action="export-trace">Export Trace</button>
          <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
        </div>` : ""}
        <button type="button" id="inline-back">Menu</button>
      </div>
    </div>`;
  board.appendChild(overlay);
}

function startGame(opts: { variationId?: string; seed?: number; actions?: string[] } = {}): void {
  if (!entry?.create) return;
  stopWorkerOrchestrator();
  clearTickTimer();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;

  const variationId = opts.variationId
    ?? entry.variations[variationCursor]?.id
    ?? entry.variations[0]!.id;
  const matched = entry.variations.findIndex((item) => item.id === variationId);
  variationCursor = matched >= 0 ? matched : 0;

  const seed = opts.seed ?? randomSeed(currentSeed);
  let nextGame: PlayableGame | undefined;
  let actions: string[] = [];
  if (opts.actions && opts.seed !== undefined) {
    const restored = restoreGame(entry, {
      schemaVersion: 1,
      ownerId: signedInUser()?.id ?? "",
      gameId: entry.id,
      gameVersion: entry.version,
      variationId,
      seed,
      actions: opts.actions,
    });
    if (restored) {
      nextGame = restored.game;
      actions = restored.actions;
    }
  }
  if (!nextGame) {
    nextGame = entry.create(variationId);
    nextGame.reset(seed);
    actions = [];
  }

  game = nextGame;
  currentSeed = seed;
  currentVariationId = variationId;
  currentActions = actions;
  gameStartedAt = Date.now();
  actionsTaken = actions.length;
  gameEnded = false;
  replaying = false;
  overlayPaused = false;
  hidePauseDialog();

  activeTrace = createOverlayTrace(entry, variationId, seed, gameStartedAt);
  for (const action of actions) {
    appendOverlayAction(
      activeTrace,
      action,
      action === "tick" || action === "bot_move" ? "environment" : "human",
    );
  }
  sessionReceiptId = activeTrace.gameId;
  gameSessionId = activeTrace.gameId;
  persistTrace(activeTrace);
  persistActiveGame();
  captureOverlayEvent("game.started", { game_type: entry.id, variation_id: variationId });

  screen = "game";
  renderGameScreen();
  attachWorkerOrchestrator(game);
  enterScheduler();
}

function resumeSavedGame(): void {
  if (!savedGame) return;
  const selected = findGame(savedGame.gameId);
  if (!selected || !isPlayable(selected)) return;
  entry = selected;
  startGame({
    variationId: savedGame.variationId,
    seed: savedGame.seed,
    actions: savedGame.actions,
  });
}

function restartGame(): void {
  if (!entry) return;
  const variationId = currentVariation();
  const previousSeed = currentSeed;
  if (game && !gameEnded) endGame("restart");
  clearSavedGame();
  savedGame = undefined;
  startGame({ variationId, seed: randomSeed(previousSeed) });
}

function launchGame(gameId: string, variationId?: string): boolean {
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return false;
  entry = selected;
  const id = variationId && selected.variations.some((item) => item.id === variationId)
    ? variationId
    : selected.variations[0]!.id;
  startGame({ variationId: id });
  return true;
}

