function openArcade(): void {
  cursor = -1;
  const launch = pendingLaunch;
  pendingLaunch = undefined;
  if (launch && launchGame(launch.game, launch.variation)) return;
  const query = new URLSearchParams(window.location.search);
  const queryGame = query.get("game");
  if (queryGame && launchGame(queryGame, query.get("variation") ?? undefined)) return;
  if (settings.resumeLastGame && savedGame) {
    resumeSavedGame();
    return;
  }
  screen = "menu";
  drawMenu();
}

/** Called once a session exists: leave the gate and show the arcade. */
function unlockTui(user: AuthUser): void {
  setSignedInUser(user);
  const saved = loadSavedGame();
  savedGame = saved?.ownerId === user.id ? saved : undefined;
  openArcade();
  renderAccountChip();
  renderSignInBar();
}

